import { Readable } from 'node:stream';
import { createGzip } from 'node:zlib';
import { pipeline } from 'node:stream/promises';
import fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import mongoose from 'mongoose';
import { archiveEntries } from './company-tar.js';
import { HttpError } from './security.js';
import { models, Renewal, RenewalPayment, AuditLog, Membership, TaskUpdate, StoredFile, JournalEntry, Transfer, ApprovalRequest, Invoice, Expense, Project } from '../models.js';

/** Aggregate counts are generated by the database, not a 3,000-row dashboard limit. */
export const exportModels: Record<string,mongoose.Model<any>> = {
  ...models, renewals:Renewal, renewalPayments:RenewalPayment, taskUpdates:TaskUpdate, memberships:Membership,
  storedFiles:StoredFile, journalEntries:JournalEntry, auditLogs:AuditLog,
};
export async function companyImpact(companyId:string) {
  const counts:Record<string,number>={};
  await Promise.all(Object.entries(exportModels).map(async([entity,Model])=>{
    const count=await Model.countDocuments({companyId});
    if(count) counts[entity]=count;
  }));
  const incomingTransfers=await Transfer.countDocuments({targetCompanyId:companyId,companyId:{$ne:companyId}});
  const pendingApprovals=await ApprovalRequest.countDocuments({companyId,status:'pending'});
  const openInvoices=await Invoice.countDocuments({companyId,status:{$nin:['paid','void','cancelled','archived']}});
  const openExpenses=await Expense.countDocuments({companyId,status:{$in:['pending','approved']}});
  const openProjects=await Project.countDocuments({companyId,status:{$in:['planning','in-progress','on-hold']}});
  const supportedOperations=(counts.tasks||0)+(counts.taskUpdates||0)+(counts.events||0);
  const hasBusinessData=Object.entries(counts).some(([name,count])=>count>0&&!['memberships','auditLogs'].includes(name));
  return {counts,incomingTransfers,pendingApprovals,openInvoices,openExpenses,openProjects,
    supportedOperations,hasBusinessData,
    deletionEligible:!hasBusinessData && !incomingTransfers && !pendingApprovals};
}

/** Stream a complete, auditable TAR.GZ: NDJSON records + private binary uploads. */
export async function streamCompanyArchive(companyId:string,company:any,res:import('express').Response) {
  const folder=await fs.mkdtemp(path.join(os.tmpdir(),'bitstek-company-export-'));
  const dataFile=path.join(folder,'records.ndjson');
  try {
    const handle=await fs.open(dataFile,'w',0o600);
    try {
      for(const [collection,Model] of Object.entries(exportModels)){
        for await(const doc of Model.find({companyId}).lean().cursor()){
          await handle.writeFile(JSON.stringify({collection,doc})+'\n');
        }
      }
    } finally{await handle.close();}
    const fileRows=await StoredFile.find({companyId}).select('storageName originalName size').lean();
    const attachments:Array<{name:string;file:string;size:number}>=[];
    const missingDocuments:string[]=[];
    const uploadRoot=path.resolve(process.env.UPLOAD_DIR||'./private-uploads');
    for(const file of fileRows){
      const name=String(file.storageName);
      if(!/^[a-f\d-]{16,64}$/i.test(name)){missingDocuments.push(String(file._id));continue;}
      const location=path.join(uploadRoot,name);
      try{
        const stat=await fs.stat(location);
        if(!stat.isFile())throw new Error('Not a file');
        attachments.push({name:`documents/${name}`,file:location,size:stat.size});
      }catch{missingDocuments.push(String(file._id));}
    }
    if(missingDocuments.length) throw new HttpError(409,`Export blocked: ${missingDocuments.length} referenced document(s) are unavailable. Restore upload storage before export.`);
    const manifest=Buffer.from(JSON.stringify({format:'bitstek-workspace-company-v1',exportedAt:new Date().toISOString(),company,
      collections:Object.keys(exportModels),documents:attachments.length,warning:'This archive contains sensitive data and must be stored securely.'},null,2));
    const dataStat=await fs.stat(dataFile);
    const entries=[{name:'manifest.json',content:manifest,size:manifest.length},
      {name:'records.ndjson',file:dataFile,size:dataStat.size},...attachments];
    res.status(200);
    res.setHeader('Content-Type','application/gzip');
    res.setHeader('Content-Disposition',`attachment; filename="${String(company.code||companyId).replace(/[^a-z0-9_-]/gi,'_')}-backup.tar.gz"`);
    res.setHeader('Cache-Control','no-store');
    await pipeline(Readable.from(archiveEntries(entries)),createGzip({level:6}),res);
  } finally{await fs.rm(folder,{recursive:true,force:true});}
}

/** Only operational tasks/calendar are safe for an automated company move.
 * All financial, trading, client and training data remains untouched and exportable.
 */
export async function operationsMigrationPreview(sourceId:string,targetId:string) {
  const { tasks: Task, events: Event } = models;
  const [tasks,events]=await Promise.all([
    Task.find({companyId:sourceId}).select('_id ownerId assigneeIds linkedId').lean(),
    Event.find({companyId:sourceId}).select('_id attendeeIds').lean(),
  ]);
  const users=new Set<string>();
  for(const task of tasks){
    if(task.linkedId)throw new Error('Tasks linked to other business records must be unlinked or exported before moving');
    if(task.ownerId)users.add(String(task.ownerId));
    for(const id of task.assigneeIds||[])users.add(String(id));
  }
  for(const event of events)for(const id of event.attendeeIds||[])users.add(String(id));
  const userIds=[...users];
  const eligible=await Membership.find({companyId:targetId,userId:{$in:userIds},active:true,removedAt:{$exists:false}}).select('userId').lean();
  const targetMembers=new Set(eligible.map(m=>String(m.userId)));
  const {TenantMembership}=await import('../saas/models.js');
  const {currentTenant}=await import('../saas/tenant-context.js');
  const tenantAdmins=await TenantMembership.find({tenantId:currentTenant(),userId:{$in:userIds},role:'super_admin',active:true}).select('userId').lean();
  for(const member of tenantAdmins)targetMembers.add(String(member.userId));
  const unassigned=userIds.filter(id=>!targetMembers.has(id));
  const taskIds=tasks.map(t=>t._id);
  const taskUpdates=await TaskUpdate.countDocuments({companyId:sourceId,taskId:{$in:taskIds}});
  const blockingApprovals=await ApprovalRequest.countDocuments({companyId:sourceId,recordType:'tasks',recordId:{$in:taskIds}});
  return {tasks:tasks.length,events:events.length,taskUpdates,blockingApprovals,
    unassignedUsers:unassigned,eligible:!unassigned.length&&!blockingApprovals};
}
